/* ===================== BÀI 14 · ADD/ADC, SUB/SBB và mở rộng dấu ===================== */
/* Bài 14 · ADD/ADC, SUB/SBB và mở rộng dấu (AMTS-EMB-002-M04-L02, X86-014) — sinh bởi tools/author/mpu8086/l14.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8086 và bài tập chấm tự động (đề, code mẫu, test). Lời giải không nằm ở đây. */
const P14=[{"label": "Ví dụ: cộng 32 bit bằng ADD rồi ADC", "code": "; Ví dụ 1: cộng 32 bit bằng ADD rồi ADC\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\na       DD      0001F000H\nb       DD      00002345H\nc       DD      ?                       ; c = a + b\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AX, WORD PTR a          ; word thấp của a\n        ADD     AX, WORD PTR b          ; F000h + 2345h = 1345h, CF = 1\n        MOV     WORD PTR c, AX          ; MOV không đổi CF\n        MOV     AX, WORD PTR a+2        ; word cao của a\n        ADC     AX, WORD PTR b+2        ; 0001h + 0000h + CF = 0002h\n        MOV     WORD PTR c+2, AX\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Bấm Từng bước tới ADD AX, WORD PTR b: AX = 1345h và cờ CF sáng lên (số nhớ ra khỏi bit 15). MOV WORD PTR c, AX không đổi CF. ADC AX, WORD PTR b+2 cộng thêm CF: 0001h + 0000h + 1 = 0002h. Xem c = 45 13 02 00 (little-endian) ở phần Bộ nhớ. Đoán trước: sau ADC, AX bằng bao nhiêu? Đáp án 0002h."}, {"label": "Lỗi: dùng ADD cho word cao, mất số nhớ", "code": "; Ví dụ 2 (lỗi cố ý): word cao cộng bằng ADD\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\na       DD      0001F000H\nb       DD      00002345H\nc       DD      ?                       ; c = a + b\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AX, WORD PTR a          ; word thấp của a\n        ADD     AX, WORD PTR b          ; F000h + 2345h = 1345h, CF = 1\n        MOV     WORD PTR c, AX          ; MOV không đổi CF\n        MOV     AX, WORD PTR a+2        ; word cao của a\n        ADD     AX, WORD PTR b+2        ; sai: bỏ mất CF của word thấp\n        MOV     WORD PTR c+2, AX\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Lỗi logic cố ý: giống Ví dụ 1 nhưng word cao cộng bằng ADD, bỏ qua CF = 1 của word thấp. Kết quả c = 0001 1345h, thiếu đúng 10000h (65 536). Chương trình chạy hết, không có thông báo lỗi nào. Sửa: ADC AX, WORD PTR b+2 như Ví dụ 1. Đoán trước: sau lệnh ADD thứ hai, AX bằng bao nhiêu? Đáp án 0001h."}, {"label": "Ví dụ: trừ 32 bit bằng SUB rồi SBB", "code": "; Ví dụ 3: trừ 32 bit bằng SUB rồi SBB, số trong DX:AX\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nx       DD      00030000H\ny       DD      1\nz       DD      ?                       ; z = x - y\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AX, WORD PTR x          ; DX:AX = x\n        MOV     DX, WORD PTR x+2\n        SUB     AX, WORD PTR y          ; 0000h - 0001h = FFFFh, CF = 1\n        SBB     DX, WORD PTR y+2        ; 0003h - 0000h - CF = 0002h\n        MOV     WORD PTR z, AX\n        MOV     WORD PTR z+2, DX\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Số 32 bit nằm trong cặp DX:AX. SUB AX, WORD PTR y: 0000h − 0001h phải mượn nên AX = FFFFh, CF = 1. SBB DX, WORD PTR y+2 trừ thêm CF: 0003h − 0 − 1 = 0002h. z = FF FF 02 00 = 0002FFFFh. Đoán trước: sau SUB, CF bằng bao nhiêu? Đáp án 1."}, {"label": "Ví dụ: CBW, CWD mở rộng dấu; NEG", "code": "; Ví dụ 4: CBW, CWD mở rộng dấu; NEG đổi dấu\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     AL, 0FBH                ; -5 dạng byte\n        CBW                             ; AX = FFFBh (-5)\n        MOV     BX, AX\n        MOV     AL, 7BH                 ; +123\n        CBW                             ; AX = 007Bh\n        MOV     SI, AX\n        MOV     AX, 8000H               ; -32768\n        CWD                             ; DX:AX = FFFF 8000h\n        MOV     CX, 5\n        NEG     CX                      ; CX = 0 - 5 = FFFBh, CF = 1\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "CBW chép bit 7 của AL vào AH: FBh (−5) thành FFFBh, 7Bh (+123) thành 007Bh. CWD chép bit 15 của AX vào DX: 8000h cho DX = FFFFh. NEG CX tính 0 − 5 = FFFBh và CF = 1. Nhìn AH, DX đổi sau từng lệnh ở phần Thanh ghi. Đoán trước: sau CBW đầu tiên, AX bằng bao nhiêu? Đáp án FFFBh."}, {"label": "Bẫy: MOV AH, 0 không giữ dấu", "code": "; Ví dụ 5 (bẫy): MOV AH, 0 không giữ dấu\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nw       DW      1000\nsai     DW      ?\ndung    DW      ?\nd       DB      -5                      ; byte có dấu: FBh\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AL, d\n        MOV     AH, 0                   ; AX = 00FBh = 251: mất dấu\n        ADD     AX, w                   ; 1251: sai\n        MOV     sai, AX\n        MOV     AL, d\n        CBW                             ; AX = FFFBh = -5\n        ADD     AX, w                   ; 995: đúng\n        MOV     dung, AX\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Bẫy cố ý: d = FBh là −5. MOV AH, 0 coi nó là 251 nên sai = 1000 + 251 = 1251 (04E3h). CBW giữ dấu: AX = FFFBh, dung = 1000 − 5 = 995 (03E3h). Đoán trước: sau MOV AH, 0, AX bằng bao nhiêu? Đáp án 00FBh."}, {"label": "Bẫy: INC không đặt CF cho ADC", "code": "; Ví dụ 6 (bẫy): INC không đặt CF\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nn       DD      0000FFFFH               ; tăng 1 bằng INC: sai\nm       DD      0000FFFFH               ; tăng 1 bằng ADD: đúng\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        CLC                             ; CF = 0 trước khi thử\n        INC     WORD PTR n              ; FFFFh → 0000h, CF vẫn 0\n        ADC     WORD PTR n+2, 0         ; không có số nhớ: vẫn 0000h\n        ADD     WORD PTR m, 1           ; FFFFh → 0000h, CF = 1\n        ADC     WORD PTR m+2, 0         ; 0000h + 0 + 1 = 0001h\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Bẫy cố ý: INC WORD PTR n đưa FFFFh về 0000h nhưng không đổi CF (vẫn 0 sau CLC), nên ADC word cao không cộng gì: n = 0000 0000h (sai, đúng phải là 0001 0000h). ADD WORD PTR m, 1 đặt CF = 1 nên m = 0001 0000h. Đoán trước: ngay sau INC WORD PTR n, CF bằng bao nhiêu? Đáp án 0."}, {"label": "Ví dụ: cộng số có dấu vào tổng 32 bit", "code": "; Ví dụ 7: cộng số 16 bit có dấu vào tổng 32 bit\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\ntong    DD      100000                  ; 000186A0h\nv       DW      -300                    ; FED4h\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AX, v\n        CWD                             ; DX:AX = FFFF FED4h = -300\n        ADD     WORD PTR tong, AX       ; word thấp, CF = 1\n        ADC     WORD PTR tong+2, DX     ; 0001h + FFFFh + 1 = 0001h\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "v = −300 (FED4h). CWD tạo DX = FFFFh để DX:AX = −300 dạng 32 bit. ADD word thấp: 86A0h + FED4h = 8574h, CF = 1; ADC word cao: 0001h + FFFFh + 1 = 0001h (số nhớ ra khỏi bit 31 bỏ đi). tong = 00018574h = 99 700. Đoán trước: sau CWD, DX bằng bao nhiêu? Đáp án FFFFh."}];
const sim14=makeX86Sim(document.getElementById("x86-l14"),{id:"s14",presets:P14,file:"BAI14.ASM"});
makeX86Ex(document.getElementById("ex-l14"),sim14,[{"t": "Tổng và hiệu hai phím", "d": "Đọc hai phím bằng INT 21h hàm 08h (code mẫu đã đặt mã phím 1 vào BL, phím 2 vào CL). Ghi vào biến word tong = mã phím 1 + mã phím 2 (hiểu là số không dấu) và vào biến word hieu = mã phím 1 − mã phím 2 (số có dấu, bù 2 trong 16 bit). Không in gì; kết thúc bằng INT 21h hàm 4Ch.", "start": "; Bài tập 1: tổng và hiệu hai phím, dạng word\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\ntong    DW      ?                       ; phím 1 + phím 2 (không dấu)\nhieu    DW      ?                       ; phím 1 - phím 2 (có dấu)\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AH, 08H\n        INT     21H\n        MOV     BL, AL                  ; BL = mã phím 1\n        MOV     AH, 08H\n        INT     21H\n        MOV     CL, AL                  ; CL = mã phím 2\n; Viết code ở đây: tong = BL + CL, hieu = BL - CL\n; (16 bit, chọn đúng cách mở rộng byte → word)\n\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "AB", "mem": [{"at": "tong", "word": 131}, {"at": "hieu", "word": 65535}]}, {"in": "~~", "mem": [{"at": "tong", "word": 252}, {"at": "hieu", "word": 0}]}, {"in": "~ ", "mem": [{"at": "tong", "word": 158}, {"at": "hieu", "word": 94}]}, {"in": " ~", "mem": [{"at": "tong", "word": 158}, {"at": "hieu", "word": 65442}]}, {"in": "zA", "mem": [{"at": "tong", "word": 187}, {"at": "hieu", "word": 57}]}, {"in": "09", "mem": [{"at": "tong", "word": 105}, {"at": "hieu", "word": 65527}]}]}, {"t": "Trừ dần số 32 bit", "d": "Biến tong (DD) bắt đầu bằng 00010100h (65792). Đọc 3 phím bằng INT 21h hàm 08h (vòng lặp đã có trong code mẫu); mỗi phím, trừ mã ASCII của phím (số không dấu 0–255) khỏi tong, tính đủ 32 bit. Không in gì; kết thúc bằng INT 21h hàm 4Ch.", "start": "; Bài tập 2: trừ dần mã 3 phím khỏi số 32 bit\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\ntong    DD      00010100H               ; 65792\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     CX, 3\ndoc:\n        MOV     AH, 08H\n        INT     21H                     ; AL = mã phím (0..255)\n; Viết code ở đây: tong = tong - AL (32 bit)\n\n        LOOP    doc\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "   ", "mem": [{"at": "tong", "bytes": [160, 0, 1, 0]}]}, {"in": "~~~", "mem": [{"at": "tong", "bytes": [134, 255, 0, 0]}]}, {"in": "AAA", "mem": [{"at": "tong", "bytes": [61, 0, 1, 0]}]}, {"in": "~~ ", "mem": [{"at": "tong", "bytes": [228, 255, 0, 0]}]}, {"in": "!!!", "mem": [{"at": "tong", "bytes": [157, 0, 1, 0]}]}, {"in": "zz~", "mem": [{"at": "tong", "bytes": [142, 255, 0, 0]}]}]}, {"t": "Cộng dồn 32 bit nhanh", "d": "Biến tong (DD) bắt đầu bằng 0001FF00h. Đọc 4 phím bằng INT 21h hàm 08h và cộng mã ASCII của từng phím (không dấu) vào tong, tính đủ 32 bit. Code mẫu đúng nhưng cộng trên ô nhớ mỗi vòng nên chậm. Viết lại để đạt cả giới hạn chu kỳ và giới hạn số byte mã. Không in gì; kết thúc bằng INT 21h hàm 4Ch.", "start": "; Bài tập 3: cộng dồn mã 4 phím vào số 32 bit\n; Bản này đúng nhưng chậm: mỗi vòng đọc và ghi\n; bộ nhớ 4 lần. Hãy viết lại.\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\ntong    DD      0001FF00H               ; 130816\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     CX, 4\ndoc:\n        MOV     AH, 08H\n        INT     21H\n        MOV     AH, 0                   ; AX = mã phím\n        ADD     WORD PTR tong, AX       ; 16 + 6 = 22 chu kỳ\n        ADC     WORD PTR tong+2, 0      ; 17 + 6 = 23 chu kỳ\n        LOOP    doc\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "AAAA", "mem": [{"at": "tong", "bytes": [4, 0, 2, 0]}]}, {"in": "    ", "mem": [{"at": "tong", "bytes": [128, 255, 1, 0]}]}, {"in": "~~~~", "mem": [{"at": "tong", "bytes": [248, 0, 2, 0]}]}, {"in": "!!!!", "mem": [{"at": "tong", "bytes": [132, 255, 1, 0]}]}, {"in": "zz  ", "mem": [{"at": "tong", "bytes": [52, 0, 2, 0]}]}, {"in": "0~ z", "mem": [{"at": "tong", "bytes": [72, 0, 2, 0]}]}], "perf": {"cycles": 450, "bytes": 45}}]);

makeQuiz("quiz14","score14",[{"q": "DX:AX = 0001 FFFFh. Sau hai lệnh sau, DX:AX bằng bao nhiêu?<pre class=\"mp-asm\">        ADD     AX, 1\n        ADC     DX, 0<\/pre>", "o": ["0001 0000h", "0002 FFFFh", "0002 0000h", "0001 0001h"], "a": 2, "e": "ADD AX, 1: FFFFh + 1 = 0000h và CF = 1. ADC DX, 0: 0001h + 0 + 1 = 0002h. Đây là phép tăng 32 bit đúng."}, {"q": "AL = F0h. Sau lệnh CBW, AX bằng bao nhiêu?", "o": ["00F0h", "FFF0h", "F0F0h", "0F00h"], "a": 1, "e": "CBW chép bit 7 của AL (bằng 1) vào cả 8 bit của AH, nên AX = FFF0h = −16, cùng giá trị có dấu với byte F0h."}, {"q": "AX chứa số có dấu −1000. Cần DX:AX bằng −1000 dạng 32 bit. Lệnh nào đúng?", "o": ["<code>XOR DX, DX<\/code>", "<code>MOV DX, 0<\/code>", "<code>CBW<\/code>", "<code>CWD<\/code>"], "a": 3, "e": "CWD chép bit dấu của AX vào DX: DX = FFFFh. Hai cách xóa DX tạo số dương 64 536; CBW chỉ mở rộng AL → AX."}, {"q": "Đoạn sau muốn tăng số 32 bit n (DD) thêm 1. Vì sao nó sai khi word thấp của n là FFFFh?<pre class=\"mp-asm\">        INC     WORD PTR n\n        ADC     WORD PTR n+2, 0<\/pre>", "o": ["INC không đổi CF nên ADC không nhận được số nhớ", "INC không được dùng với ô nhớ trên 8086", "ADC chỉ cộng được thanh ghi, không cộng ô nhớ", "WORD PTR n+2 trỏ vào word thấp của n"], "a": 0, "e": "INC đưa FFFFh về 0000h nhưng giữ nguyên CF. Phải dùng ADD WORD PTR n, 1 (đặt CF = 1) rồi ADC (Ví dụ 6)."}, {"q": "Số 32 bit nằm trong DX:BX (DX là word cao). Cộng AX (không dấu) vào số đó: đoạn nào đúng?", "o": ["<code>ADD BX, AX<\/code> / <code>ADC DX, 0<\/code>", "<code>ADD BX, AX<\/code> / <code>ADD DX, 0<\/code>", "<code>ADD DX, AX<\/code> / <code>ADC BX, 0<\/code>", "<code>ADD BX, AX<\/code> / <code>INC DX<\/code>"], "a": 0, "e": "Word thấp trước bằng ADD, word cao sau bằng ADC với 0 để nhận số nhớ. ADD DX, 0 bỏ mất số nhớ; INC DX luôn cộng 1 kể cả khi không có số nhớ."}]);

